// Builds a downloadable poster of the mind map: the radial map plus the full
// details of every topic (explanation, key points, example and diagram).
// No extra libraries: the SVG is generated by hand and rasterized with <canvas>.

const WIDTH = 1400;
const MAP_HEIGHT = 1000;
const CX = WIDTH / 2;
const CY = 505;
const CENTER_R = 118;
const BRANCH_R = 84;
const RX = 430;
const RY = 300;
const COLORS = ["#7c83ff", "#35d0ba", "#f2b705", "#ef6f91"];
const FONT = "'Segoe UI', system-ui, -apple-system, Arial, sans-serif";

/* ------------------------------------------------------------------ */
/* Text helpers                                                        */
/* ------------------------------------------------------------------ */

function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function slug(value) {
  return (
    String(value || "lecture")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 60) || "lecture"
  );
}

// Rough width estimate so labels wrap by real width instead of character count.
function measure(text, fontSize) {
  let total = 0;
  for (const ch of String(text)) {
    if (ch === " ") total += fontSize * 0.3;
    else if ("il.,;:!|'`".includes(ch)) total += fontSize * 0.28;
    else if ("mwMW@%&#".includes(ch)) total += fontSize * 0.92;
    else if (/[A-Z]/.test(ch)) total += fontSize * 0.68;
    else if (/[0-9]/.test(ch)) total += fontSize * 0.58;
    else total += fontSize * 0.55;
  }
  return total;
}

// Wrap text to a max pixel width, cap the number of lines with an ellipsis.
function splitLines(text, maxWidth, maxLines, fontSize) {
  const words = String(text || "").trim().split(/\s+/).filter(Boolean);
  const lines = [];
  let current = "";

  for (const word of words) {
    const candidate = current ? `${current} ${word}` : word;
    if (!current || measure(candidate, fontSize) <= maxWidth) {
      current = candidate;
    } else {
      lines.push(current);
      current = word;
    }
  }
  if (current) lines.push(current);

  // Break single words that are wider than a whole line.
  const flat = [];
  for (const line of lines) {
    if (measure(line, fontSize) <= maxWidth) {
      flat.push(line);
      continue;
    }
    let chunk = "";
    for (const ch of line) {
      if (chunk && measure(chunk + ch, fontSize) > maxWidth) {
        flat.push(chunk);
        chunk = ch;
      } else {
        chunk += ch;
      }
    }
    if (chunk) flat.push(chunk);
  }

  if (flat.length > maxLines) {
    const kept = flat.slice(0, maxLines);
    kept[maxLines - 1] = `${kept[maxLines - 1].replace(/[\s.,;:]$/, "")}…`;
    return kept;
  }
  return flat.length ? flat : [""];
}

function textEl(line, x, y, options = {}) {
  const {
    fontSize = 13,
    fill = "#c9d1d9",
    weight = 400,
    italic = false,
    anchor = "start",
    letterSpacing = 0,
  } = options;
  return (
    `<text x="${x.toFixed(1)}" y="${y.toFixed(1)}" text-anchor="${anchor}" ` +
    `font-family="${FONT}" font-size="${fontSize}" font-weight="${weight}"` +
    `${italic ? ' font-style="italic"' : ""}` +
    `${letterSpacing ? ` letter-spacing="${letterSpacing}"` : ""} ` +
    `fill="${fill}">${esc(line)}</text>`
  );
}

// Pushes wrapped lines into `parts`; returns the used height in pixels.
function pushLines(parts, text, x, top, options) {
  const {
    width,
    fontSize,
    lineHeight,
    fill,
    weight = 400,
    italic = false,
    maxLines = 200,
  } = options;
  const lines = splitLines(text, width, maxLines, fontSize);
  lines.forEach((line, i) => {
    parts.push(
      textEl(line, x, top + i * lineHeight + fontSize * 0.8, {
        fontSize,
        fill,
        weight,
        italic,
      })
    );
  });
  return lines.length * lineHeight;
}

function labelEl(text, x, top, color) {
  return textEl(text, x, top + 10, {
    fontSize: 11,
    fill: color,
    weight: 800,
    letterSpacing: 1.4,
  });
}

/* ------------------------------------------------------------------ */
/* Radial map                                                          */
/* ------------------------------------------------------------------ */

function buildMap(topics, title) {
  const parts = [];
  const titleLines = splitLines(title, 208, 4, 21);

  const branches = topics.map((topic, i) => {
    const angle = (i / (topics.length || 1)) * Math.PI * 2 - Math.PI / 2;
    const x = CX + Math.cos(angle) * RX;
    const y = CY + Math.sin(angle) * RY;
    const color = COLORS[i % COLORS.length];
    const labelLines = splitLines(topic?.heading || `Topic ${i + 1}`, 148, 3, 13);
    const points = Array.isArray(topic?.keyPoints) ? topic.keyPoints.length : 0;
    const count = points || 1;
    const countText = `${count} point${count === 1 ? "" : "s"}`;
    return { x, y, color, labelLines, countText };
  });

  parts.push(`<rect width="${WIDTH}" height="${MAP_HEIGHT}" fill="url(#mm-bg)"/>`);
  parts.push(
    `<rect x="18" y="18" width="${WIDTH - 36}" height="${MAP_HEIGHT - 36}" rx="26" ` +
      `fill="none" stroke="#30363d" stroke-width="2"/>`
  );
  parts.push(
    textEl("MIND MAP", 52, 64, {
      fontSize: 15,
      fill: "#7c83ff",
      weight: 800,
      letterSpacing: 3,
    })
  );

  // Connector lines from centre to every branch.
  branches.forEach((b) => {
    const dx = b.x - CX;
    const dy = b.y - CY;
    const len = Math.hypot(dx, dy) || 1;
    const ux = dx / len;
    const uy = dy / len;
    const x1 = CX + ux * (CENTER_R + 6);
    const y1 = CY + uy * (CENTER_R + 6);
    const x2 = b.x - ux * (BRANCH_R + 6);
    const y2 = b.y - uy * (BRANCH_R + 6);
    parts.push(
      `<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" ` +
        `stroke="${b.color}" stroke-width="2" stroke-opacity="0.6" stroke-linecap="round"/>`
    );
  });

  // Branch circles + point badges.
  branches.forEach((b) => {
    const badgeW = Math.max(74, b.countText.length * 7 + 24);
    const badgeY = b.y + BRANCH_R + 18;
    parts.push(
      `<circle cx="${b.x.toFixed(1)}" cy="${b.y.toFixed(1)}" r="${BRANCH_R}" ` +
        `fill="#161b22" stroke="${b.color}" stroke-width="4"/>`
    );
    parts.push(
      `<circle cx="${b.x.toFixed(1)}" cy="${b.y.toFixed(1)}" r="${BRANCH_R + 7}" ` +
        `fill="none" stroke="${b.color}" stroke-width="1.5" stroke-opacity="0.28"/>`
    );
    b.labelLines.forEach((line, i) => {
      const y =
        b.y +
        (i - (b.labelLines.length - 1) / 2) * 17 +
        13 * 0.35;
      parts.push(
        textEl(line, b.x, y, { fontSize: 13, fill: "#ffffff", weight: 700, anchor: "middle" })
      );
    });
    parts.push(
      `<rect x="${(b.x - badgeW / 2).toFixed(1)}" y="${badgeY}" width="${badgeW}" height="24" ` +
        `rx="12" fill="#0d1117" stroke="${b.color}" stroke-width="1.5" stroke-opacity="0.75"/>`
    );
    parts.push(
      textEl(b.countText, b.x, badgeY + 16, {
        fontSize: 12,
        fill: b.color,
        weight: 700,
        anchor: "middle",
      })
    );
  });

  // Centre node.
  parts.push(
    `<circle cx="${CX}" cy="${CY}" r="${CENTER_R + 10}" fill="none" stroke="#7c83ff" ` +
      `stroke-width="1.5" stroke-opacity="0.22"/>`
  );
  parts.push(
    `<circle cx="${CX}" cy="${CY}" r="${CENTER_R}" fill="url(#mm-center)" stroke="#7c83ff" stroke-width="5"/>`
  );
  titleLines.forEach((line, i) => {
    const y = CY + (i - (titleLines.length - 1) / 2) * 26 + 21 * 0.35;
    parts.push(
      textEl(line, CX, y, { fontSize: 21, fill: "#ffffff", weight: 800, anchor: "middle" })
    );
  });

  return parts;
}

/* ------------------------------------------------------------------ */
/* Topic diagrams (flow / concept / compare)                           */
/* ------------------------------------------------------------------ */

function buildVisual(visual, x, y, width, color) {
  const pad = 16;
  const innerW = width - pad * 2;
  const content = [];
  let cy = pad;

  const title = String(visual?.title || "").trim();
  if (title) {
    cy += pushLines(content, title, pad, cy, {
      width: innerW,
      fontSize: 13,
      lineHeight: 19,
      fill: "#e6edf3",
      weight: 700,
      maxLines: 2,
    });
    cy += 6;
  }

  if (visual.type === "flow") {
    const steps = (visual.steps || []).map((s) => String(s).trim()).filter(Boolean);
    steps.forEach((step, i) => {
      const lines = splitLines(step, innerW - 34, 30, 13);
      const rowH = Math.max(28, lines.length * 18 + 8);
      if (i < steps.length - 1) {
        content.push(
          `<line x1="${pad + 11}" y1="${cy + 23}" x2="${pad + 11}" y2="${cy + rowH + 3}" ` +
            `stroke="${color}" stroke-width="2" stroke-opacity="0.4"/>`
        );
      }
      content.push(
        `<circle cx="${pad + 11}" cy="${cy + 13}" r="10" fill="#0d1117" stroke="${color}" stroke-width="1.5"/>`
      );
      content.push(
        textEl(String(i + 1), pad + 11, cy + 17, {
          fontSize: 10.5,
          fill: color,
          weight: 700,
          anchor: "middle",
        })
      );
      lines.forEach((line, li) =>
        content.push(
          textEl(line, pad + 32, cy + 17 + li * 18, { fontSize: 13, fill: "#c9d1d9" })
        )
      );
      cy += rowH;
    });
  } else if (visual.type === "concept") {
    const centerText = String(visual.center || "").trim();
    const branches = (visual.branches || []).map((b) => String(b).trim()).filter(Boolean);

    if (centerText) {
      const cLines = splitLines(centerText, innerW - 60, 2, 14);
      const textW = Math.max(...cLines.map((l) => measure(l, 14)));
      const chipW = Math.min(innerW, Math.max(130, textW + 40));
      const chipH = cLines.length * 20 + 18;
      content.push(
        `<rect x="${(pad + (innerW - chipW) / 2).toFixed(1)}" y="${cy}" width="${chipW.toFixed(1)}" ` +
          `height="${chipH}" rx="${chipH / 2}" fill="#1c2430" stroke="${color}" stroke-width="1.5"/>`
      );
      cLines.forEach((line, li) =>
        content.push(
          textEl(line, pad + innerW / 2, cy + 15 + li * 20, {
            fontSize: 14,
            fill: "#ffffff",
            weight: 700,
            anchor: "middle",
          })
        )
      );
      cy += chipH + 12;
    }

    const colGap = 10;
    const colW = (innerW - colGap) / 2;
    for (let i = 0; i < branches.length; i += 2) {
      const pair = branches.slice(i, i + 2);
      const pills = pair.map((branch) => {
        const lines = splitLines(branch, colW - 24, 3, 12.5);
        return { lines, h: lines.length * 17 + 12 };
      });
      const rowH = Math.max(...pills.map((p) => p.h));
      pills.forEach((pill, j) => {
        const px = pad + j * (colW + colGap);
        content.push(
          `<rect x="${px.toFixed(1)}" y="${cy}" width="${colW.toFixed(1)}" height="${pill.h}" rx="8" ` +
            `fill="#161d26" stroke="${color}" stroke-opacity="0.5" stroke-width="1"/>`
        );
        pill.lines.forEach((line, li) =>
          content.push(
            textEl(line, px + 12, cy + 14 + li * 17, { fontSize: 12.5, fill: "#c9d1d9" })
          )
        );
      });
      cy += rowH + 8;
    }
  } else if (visual.type === "compare") {
    const columns = (visual.columns || []).map((c) => String(c)).filter(Boolean);
    const rows = (visual.rows || [])
      .filter(Array.isArray)
      .map((r) => r.map((c) => String(c ?? "")));
    const cols = columns.length || rows.reduce((m, r) => Math.max(m, r.length), 0);

    if (cols > 0) {
      const gap = 6;
      const colW = (innerW - gap * (cols - 1)) / cols;
      const header = columns.length
        ? columns
        : Array.from({ length: cols }, (_, i) => `Column ${i + 1}`);
      const headerLines = header.map((h) => splitLines(h, colW - 16, 2, 12.5));
      const headerH = Math.max(...headerLines.map((l) => l.length * 16)) + 14;

      content.push(
        `<rect x="${pad}" y="${cy}" width="${innerW.toFixed(1)}" height="${headerH}" rx="6" fill="#1c2430"/>`
      );
      headerLines.forEach((lines, ci) =>
        lines.forEach((line, li) =>
          content.push(
            textEl(line, pad + ci * (colW + gap) + 8, cy + 12 + li * 16, {
              fontSize: 12.5,
              fill: "#e6edf3",
              weight: 700,
            })
          )
        )
      );
      cy += headerH + 2;

      rows.forEach((row, ri) => {
        const cells = Array.from({ length: cols }, (_, ci) => row[ci] ?? "");
        const lines = cells.map((c) => splitLines(c, colW - 16, 30, 12.5));
        const rowH = Math.max(...lines.map((l) => l.length * 16)) + 12;
        content.push(
          `<rect x="${pad}" y="${cy}" width="${innerW.toFixed(1)}" height="${rowH}" rx="4" ` +
            `fill="${ri % 2 ? "#121922" : "#0e141b"}"/>`
        );
        lines.forEach((cellLines, ci) =>
          cellLines.forEach((line, li) =>
            content.push(
              textEl(line, pad + ci * (colW + gap) + 8, cy + 10 + li * 16, {
                fontSize: 12.5,
                fill: "#c9d1d9",
              })
            )
          )
        );
        cy += rowH + 2;
      });
    }
  }

  const boxH = cy + pad;
  return {
    height: boxH,
    parts: [
      `<g transform="translate(${x.toFixed(1)}, ${y.toFixed(1)})">`,
      `<rect x="0" y="0" width="${width.toFixed(1)}" height="${boxH.toFixed(1)}" rx="10" ` +
        `fill="#10161d" stroke="#2b333d" stroke-width="1"/>`,
      content.join(""),
      `</g>`,
    ],
  };
}

/* ------------------------------------------------------------------ */
/* Topic detail cards                                                  */
/* ------------------------------------------------------------------ */

function buildTopicCard(topic, index, cardY) {
  const color = COLORS[index % COLORS.length];
  const cardX = 60;
  const cardW = 1280;
  const padTop = 26;
  const padBottom = 28;
  const innerX = 6;
  const innerW = cardW - 60 - innerX;

  const content = [];
  let cy = 0;

  // Heading
  cy += pushLines(content, topic?.heading || `Topic ${index + 1}`, innerX, cy, {
    width: innerW,
    fontSize: 19,
    lineHeight: 25,
    fill: "#ffffff",
    weight: 800,
    maxLines: 2,
  });
  cy += 14;

  // Explanation
  const paragraphs = String(topic?.explanation || "")
    .split(/\n\n+/)
    .map((p) => p.trim())
    .filter(Boolean);
  paragraphs.forEach((paragraph, i) => {
    cy += pushLines(content, paragraph, innerX, cy, {
      width: innerW,
      fontSize: 14.5,
      lineHeight: 22,
      fill: "#c9d1d9",
    });
    if (i < paragraphs.length - 1) cy += 9;
  });
  if (paragraphs.length) cy += 18;

  // Key points
  const points = (Array.isArray(topic?.keyPoints) ? topic.keyPoints : [])
    .map((p) => String(p || "").trim())
    .filter(Boolean);
  if (points.length) {
    content.push(labelEl("KEY POINTS", innerX, cy, color));
    cy += 20;
    points.forEach((point) => {
      const lines = splitLines(point, innerW - 22, 30, 14);
      content.push(
        `<circle cx="${innerX + 5}" cy="${(cy + 7).toFixed(1)}" r="3.2" fill="${color}"/>`
      );
      lines.forEach((line, li) =>
        content.push(
          textEl(line, innerX + 20, cy + li * 21 + 14 * 0.8, { fontSize: 14, fill: "#e6edf3" })
        )
      );
      cy += lines.length * 21 + 8;
    });
    cy += 10;
  }

  // Example
  const example = String(topic?.example || "").trim();
  if (example) {
    content.push(labelEl("EXAMPLE", innerX, cy, color));
    cy += 20;
    const exampleLines = splitLines(example, innerW - 32, 30, 13.5);
    const boxH = 32 + exampleLines.length * 20;
    content.push(
      `<rect x="${innerX}" y="${cy}" width="${innerW}" height="${boxH}" rx="10" ` +
        `fill="#1c2430" stroke="#2d3742" stroke-width="1"/>`
    );
    exampleLines.forEach((line, li) =>
      content.push(
        textEl(line, innerX + 16, cy + 16 + li * 20 + 13.5 * 0.8, {
          fontSize: 13.5,
          fill: "#c9d1d9",
          italic: true,
        })
      )
    );
    cy += boxH + 18;
  }

  // Diagram / visual
  const visual =
    topic?.visual && topic.visual.type && topic.visual.type !== "none" ? topic.visual : null;
  if (visual) {
    content.push(labelEl("DIAGRAM", innerX, cy, color));
    cy += 20;
    const vis = buildVisual(visual, innerX, cy, innerW, color);
    content.push(...vis.parts);
    cy += vis.height + 6;
  }

  const cardH = padTop + cy + padBottom;
  return {
    height: cardH,
    parts: [
      `<rect x="${cardX}" y="${cardY}" width="${cardW}" height="${cardH}" rx="16" ` +
        `fill="#161b22" stroke="#2b333d" stroke-width="1.2"/>`,
      `<rect x="${cardX + 1}" y="${cardY + 1}" width="5" height="${cardH - 2}" rx="2.5" fill="${color}"/>`,
      `<g transform="translate(${cardX + 30}, ${cardY + padTop})">${content.join("")}</g>`,
    ],
  };
}

/* ------------------------------------------------------------------ */
/* Full poster                                                         */
/* ------------------------------------------------------------------ */

function buildPoster(note) {
  const topics = (note?.topics || []).slice(0, 8);
  const title = note?.title || "Lecture";
  const parts = buildMap(topics, title);

  const detailLabelY = MAP_HEIGHT + 62;
  parts.push(
    textEl("TOPIC DETAILS", 60, detailLabelY, {
      fontSize: 15,
      fill: "#7c83ff",
      weight: 800,
      letterSpacing: 3,
    })
  );
  parts.push(
    textEl("Explanation, key points and examples for every branch", 60, detailLabelY + 24, {
      fontSize: 13,
      fill: "#6e7681",
    })
  );

  let y = detailLabelY + 48;
  topics.forEach((topic, index) => {
    const card = buildTopicCard(topic, index, y);
    parts.push(...card.parts);
    y += card.height + 26;
  });

  const totalHeight = Math.round(y + 64);
  const today = new Date().toLocaleDateString(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
  });

  parts.push(
    textEl(`AI Lecture Summarizer  ·  ${today}`, WIDTH / 2, totalHeight - 30, {
      fontSize: 13,
      fill: "#6e7681",
      anchor: "middle",
    })
  );

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${totalHeight}" viewBox="0 0 ${WIDTH} ${totalHeight}">
  <defs>
    <radialGradient id="mm-bg" cx="50%" cy="45%" r="75%">
      <stop offset="0%" stop-color="#131a24"/>
      <stop offset="65%" stop-color="#0d1117"/>
      <stop offset="100%" stop-color="#0a0e13"/>
    </radialGradient>
    <radialGradient id="mm-center" cx="50%" cy="30%" r="80%">
      <stop offset="0%" stop-color="#222c3a"/>
      <stop offset="100%" stop-color="#161b22"/>
    </radialGradient>
  </defs>
  <rect width="${WIDTH}" height="${totalHeight}" fill="#0d1117"/>
  ${parts.join("\n")}
</svg>`;

  return { svg, width: WIDTH, height: totalHeight };
}

/** Returns the poster as a standalone SVG string (useful for testing). */
export function buildMindMapSVG(note) {
  return buildPoster(note).svg;
}

function triggerDownload(blob, filename) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 5000);
}

function loadImage(url) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error("Could not render the mind map image."));
    img.src = url;
  });
}

export async function downloadMindMapPNG(note, scale = 2) {
  const { svg, width, height } = buildPoster(note);
  const svgUrl = URL.createObjectURL(
    new Blob([svg], { type: "image/svg+xml;charset=utf-8" })
  );

  try {
    const img = await loadImage(svgUrl);

    // Keep the canvas inside browser limits for very long notes.
    const maxSide = 16000;
    const maxPixels = 90_000_000;
    const safeScale = Math.max(
      1,
      Math.min(
        scale,
        maxSide / Math.max(width, height),
        Math.sqrt(maxPixels / (width * height))
      )
    );

    const canvas = document.createElement("canvas");
    canvas.width = Math.round(width * safeScale);
    canvas.height = Math.round(height * safeScale);
    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "#0d1117";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

    const blob = await new Promise((resolve) => canvas.toBlob(resolve, "image/png"));
    if (!blob) throw new Error("Could not create the PNG file.");
    triggerDownload(blob, `${slug(note?.title)}-mind-map.png`);
  } finally {
    URL.revokeObjectURL(svgUrl);
  }
}
